import { readdir, readFile, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = dirname(fileURLToPath(import.meta.url));
const sourceDir = join(root, "src");
const files = (await readdir(sourceDir))
  .filter((name) => name.endsWith(".js"))
  .sort();
const parts = await Promise.all(files.map((name) => readFile(join(sourceDir, name), "utf8")));
const header = [
  "// @generated by build.mjs from src/*.js",
  "// Do not edit this bundle directly. Maintained source files stay under 200 lines.",
  "",
].join("\n");
await writeFile(join(root, "project-module-v2.generated.js"), header + parts.join("\n"), "utf8");
